function q({registerIndicator:g,sourceValues:E,nulls:N,withAlpha:p}){g({id:"oa-reflex",name:"Ehlers Reflex Indicator (REFLEX)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:20,min:2,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"reflex",type:"line",title:"REFLEX",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#9598a1"},{price:1,title:"+1 Sigma",color:p("#ff5252",.4)},{price:-1,title:"-1 Sigma",color:p("#4caf50",.4)}],calc(u,d){const e=Math.max(2,Math.floor(Number(d.period)||20)),r=E(u,d.source??"close"),m=u.length,h=new Array(m).fill(NaN),x=e*.5,a=Math.exp(-1.414*Math.PI/x),b=2*a*Math.cos(1.414*Math.PI/x),y=-(a*a),P=1-b-y;let l=0,s=0,M=0;const f=new Array(e+1).fill(0);let o=0,i=0;for(let t=0;t<m;t++){const k=Number.isFinite(r[t])?r[t]:0,F=t>0&&Number.isFinite(r[t-1])?r[t-1]:0;M=s,s=l,l=P*(k+F)*.5+b*s+y*M,f[o]=l;const I=Math.min(t+1,e),L=(o+1)%(e+1),R=(f[L]-l)/e;let c=0;if(I>=e){for(let n=1;n<=e;n++){const S=(o-n+e+1)%(e+1);c+=l+n*R-f[S]}c/=e}o=(o+1)%(e+1),i=.04*c*c+.96*i,h[t]=i>0?c/Math.sqrt(i):0}return{reflex:N(h)}}})}export{q as default};
